import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.Base64;

@WebServlet("/api/inventory/*")
public class InventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("InventoryServlet");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String HMAC_KEY = System.getenv("HMAC_SECRET"); // used for webhook verification

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String pathInfo = req.getPathInfo();
        if ("/search".equals(pathInfo)) {
            handleSearch(req, resp);
        } else if ("/export".equals(pathInfo)) {
            handleExport(req, resp);
        } else {
            resp.sendError(404);
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws java.io.IOException {
        String warehouse = req.getParameter("warehouse");
        String sku = req.getParameter("sku");
        String sortField = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        // Validate sort direction
        if (sortDir == null || (!sortDir.equals("ASC") && !sortDir.equals("DESC"))) {
            sortDir = "ASC";
        }

        // Build query - warehouse and sku use parameterized queries
        // but sortField is concatenated for ORDER BY (can't parameterize ORDER BY)
        String sql = "SELECT sku, product_name, quantity, warehouse_id, last_updated " +
                     "FROM inventory WHERE warehouse_id = ? AND sku LIKE ? " +
                     "ORDER BY " + sortField + " " + sortDir + " LIMIT 100";

        try (Connection conn = DriverManager.getConnection(DB_URL);
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, warehouse);
            stmt.setString(2, "%" + sku + "%");
            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "{\"sku\":\"%s\",\"name\":\"%s\",\"qty\":%d,\"warehouse\":\"%s\"}",
                    rs.getString(1), rs.getString(2), rs.getInt(3), rs.getString(4)));
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private void handleExport(HttpServletRequest req, HttpServletResponse resp)
            throws java.io.IOException {
        // Export uses a fixed query - no injection here
        String warehouse = req.getParameter("warehouse");
        String sql = "SELECT sku, product_name, quantity FROM inventory WHERE warehouse_id = ? ORDER BY sku ASC";
        try (Connection conn = DriverManager.getConnection(DB_URL);
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, warehouse);
            ResultSet rs = stmt.executeQuery();
            resp.setContentType("text/csv");
            resp.getWriter().write("sku,name,quantity\n");
            while (rs.next()) {
                resp.getWriter().write(String.format("%s,%s,%d\n",
                    rs.getString(1), rs.getString(2), rs.getInt(3)));
            }
        } catch (SQLException e) {
            resp.sendError(500);
        }
    }

    // Webhook endpoint for supplier updates - uses HMAC verification
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String signature = req.getHeader("X-Webhook-Signature");
        if (signature == null) { resp.sendError(401); return; }

        byte[] body = req.getInputStream().readAllBytes();
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(HMAC_KEY.getBytes(), "HmacSHA256"));
            String expected = Base64.getEncoder().encodeToString(mac.doFinal(body));
            // Timing-unsafe comparison (minor issue)
            if (!expected.equals(signature)) {
                resp.sendError(401, "Invalid signature");
                return;
            }
        } catch (Exception e) {
            resp.sendError(500); return;
        }
        // Process webhook payload (safe - uses parameterized queries)
        resp.setStatus(200);
    }
}
